import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";

// Generated by TestResultsNativeProcessToWorkspaceBusinessTree from real
// PowerShell output, PostgreSQL file records and the Workspace file RPC.
const results = JSON.parse(
  readFileSync(
    new URL("./fixtures/workspace-results.json", import.meta.url),
    "utf8",
  ),
) as Array<{
  file: {
    id: string;
    name: string;
    path: string;
    media_type: string;
    byte_size: number;
    content_hash: string;
    created_at: string;
  };
  content: string;
}>;
const meta = JSON.parse(
  results.find((item) => item.file.name === "meta.json")!.content,
) as { files: Array<{ request_id: string; step_id: string; path: string }> };

for (const english of [false, true])
  for (const dark of [false, true])
    test(`business results and metadata ${english ? "en" : "zh"} ${dark ? "dark" : "light"}`, async ({
      page,
    }, info) => {
      await page.setViewportSize({ width: 1440, height: 900 });
      await page.addInitScript(
        ({ english, dark }) => {
          localStorage.setItem("argus.locale", english ? "en-US" : "zh-CN");
          localStorage.setItem("argus.theme", dark ? "dark" : "light");
        },
        { english, dark },
      );
      await page.goto("/login");
      await page.getByLabel(english ? "Username" : "用户名").fill("root");
      await page.getByLabel(english ? "Password" : "密码").fill("123456");
      await page
        .getByRole("button", {
          name: english ? "Sign in" : "登录",
          exact: true,
        })
        .click();
      const composer = page.locator(".argus-chat-composer");
      await composer.getByRole("textbox").fill("Business results layout");
      await composer
        .getByRole("button", { name: english ? "Send" : "发送", exact: true })
        .click();
      await expect(page).toHaveURL(/c=/);
      await expect(composer.getByRole("textbox")).toHaveValue("");
      const conversationId = new URL(page.url()).searchParams.get("c")!;
      await page.evaluate(
        ({ results, conversationId }) => {
          const key = "argus-mock:db-v14";
          const db = JSON.parse(localStorage.getItem(key)!);
          db.planv5.files[conversationId] = results.map((item) => item.file);
          for (const { file, content } of results)
            db.planv5.contents[file.id] =
              `data:${file.media_type};base64,${btoa(content)}`;
          localStorage.setItem(key, JSON.stringify(db));
        },
        { results, conversationId },
      );
      await page.reload();
      await page
        .getByRole("button", {
          name: english ? "Pinned summary" : "置顶摘要",
          exact: true,
        })
        .click();
      const popup = page.getByRole("dialog", {
        name: english ? "Pinned summary" : "置顶摘要",
        exact: true,
      });
      const tree = popup.getByRole("list", {
        name: english ? "Conversation files" : "会话文件",
        exact: true,
      });
      await tree.locator('summary[title="/workspace/results"]').click();
      await tree.locator('summary[title="/workspace/results/nginx"]').click();
      await tree
        .locator('summary[title="/workspace/results/nginx/before"]')
        .click();
      await tree
        .locator('summary[title="/workspace/results/nginx/after"]')
        .click();
      await expect(tree.locator(".argus-file-row")).toHaveCount(3);
      await expect(
        tree.getByRole("button", {
          name: `${english ? "Preview" : "预览"} status.txt`,
          exact: true,
        }),
      ).toHaveCount(2);
      expect(
        (await tree.locator("summary").allTextContents()).every(
          (name) => !/[a-f0-9]{8}-[a-f0-9]{4}-/i.test(name),
        ),
      ).toBe(true);
      await expect(
        popup.getByRole("button", { name: /删除|Delete/i }),
      ).toHaveCount(0);
      await popup.screenshot({ path: info.outputPath("business-results.png") });
      await tree
        .locator('summary[title="/workspace/results/nginx/before"]')
        .locator("..")
        .getByRole("button", {
          name: `${english ? "Preview" : "预览"} status.txt`,
          exact: true,
        })
        .click();
      await expect(
        page.getByRole("dialog", { name: "status.txt", exact: true }),
      ).toContainText("error_count=7");
      await page.keyboard.press("Escape");
      await tree
        .getByRole("button", {
          name: `${english ? "Preview" : "预览"} meta.json`,
          exact: true,
        })
        .click();
      const preview = page.getByRole("dialog", {
        name: "meta.json",
        exact: true,
      });
      await expect(preview).toContainText(meta.files[0].request_id);
      await expect(preview).toContainText(meta.files[0].step_id);
      await expect(preview).toContainText(
        "/workspace/results/nginx/before/status.txt",
      );
      await page.keyboard.press("Escape");
      const [download] = await Promise.all([
        page.waitForEvent("download"),
        tree
          .getByRole("link", {
            name: `${english ? "Download" : "下载"} meta.json`,
            exact: true,
          })
          .click(),
      ]);
      expect(download.suggestedFilename()).toBe("meta.json");
      const body = readFileSync((await download.path())!, "utf8");
      expect(JSON.parse(body)).toEqual(meta);
    });
